        this.jdbc = jdbc;
    }

    /** Every patron named on the sheet, in the order they were named. */
    public List<Patron> list(String sheetId) {
        return jdbc.query("SELECT person_id, patron_id FROM patron WHERE sheet_id = ? ORDER BY _ROWID_",
                (rs, i) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id")), sheetId);
    }

    /** Whether the person has already named this patron. */
